import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq','active'}
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def buy_id_of(o):
        return o['buy_id']

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            entry = book.get(oid)
            if entry is not None and entry['active'] and entry['qty'] > 0:
                entry['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq = next_seq()

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = heapq.heappop(opp_heap)
            if side == 'buy':
                p, s, rid = top
            else:
                negp, s, rid = top
                p = -negp

            entry = book.get(rid)
            if entry is None or not entry['active'] or entry['qty'] <= 0:
                # stale entry, discard
                continue

            # check price condition
            if typ == 'market':
                can_match = True
            else:
                if side == 'buy':
                    can_match = price >= p
                else:
                    can_match = price <= p

            if not can_match:
                # push back, stop matching
                heapq.heappush(opp_heap, top)
                break

            trade_qty = min(remaining, entry['qty'])
            trade_price = p

            if side == 'buy':
                trades.append([oid, rid, trade_price, trade_qty])
            else:
                trades.append([rid, oid, trade_price, trade_qty])

            remaining -= trade_qty
            entry['qty'] -= trade_qty

            if entry['qty'] > 0:
                heapq.heappush(opp_heap, top)
            else:
                entry['active'] = False

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            if typ == 'limit':
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}
            else:
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

    return trades

